class Solution {
public:
    vector<string> topKFrequent(vector<string>& words, int k) {
        unordered_map<string, int> counts;
        for (const string& w : words) {
            counts[w]++;
        }
        vector<string> unique;
        for (auto& p : counts) {
            unique.push_back(p.first);
        }
        sort(unique.begin(), unique.end(), [&](const string& a, const string& b) {
            if (counts[a] != counts[b]) {
                return counts[a] > counts[b];
            }
            return a < b;
        });
        unique.resize(k);
        return unique;
    }
};

class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        Map<String, Integer> counts = new HashMap<>();
        for (String w : words) {
            counts.put(w, counts.getOrDefault(w, 0) + 1);
        }
        List<String> list = new ArrayList<>(counts.keySet());
        list.sort((a, b) -> {
            int c1 = counts.get(a);
            int c2 = counts.get(b);
            if (c1 != c2) return Integer.compare(c2, c1);
            return a.compareTo(b);
        });
        return list.subList(0, k);
    }
}

var topKFrequent = function(words, k) {
    const counts = new Map();
    for (const w of words) {
        counts.set(w, (counts.get(w) || 0) + 1);
    }
    const unique = Array.from(counts.keys());
    unique.sort((a, b) => {
        const freqDiff = counts.get(b) - counts.get(a);
        if (freqDiff !== 0) return freqDiff;
        return a.localeCompare(b);
    });
    return unique.slice(0, k);
};
